PY
cd /workspace && rm -rf tmp/classes && python3 build.py /workspace/submission/src /workspace/tmp/classes 2>&1 | head -5 && echo BUILD_OK && python3 check.py /workspace/submission/src 2>&1|tail -2 && cd devtests && for t in test_audit.py test_audit2.py test_audit3.py test_random.py test_random2.py test_random3.py; do echo -n "$t: "; python3 $t 2>&1 | grep -E "^(failures|random differential failures)" | tail -1; done
